#[cfg(test)]
mod security_command_tests {
    use super::command_allowed_for_player;
    #[test]
    fn clients_can_only_run_read_only_commands() {
        for cmd in ["help", "list"] {
            assert!(command_allowed_for_player(cmd, &[]), "{cmd}");
        }
        assert!(command_allowed_for_player("time", &["query", "daytime"]));
        for (cmd, args) in [
            ("stop", vec![]),
            ("give", vec!["Steve", "diamond"]),
            ("gamemode", vec!["creative"]),
            ("setblock", vec!["0", "64", "0", "stone"]),
            ("execute", vec!["run", "stop"]),
            ("function", vec!["spine:hello"]),
            ("time", vec!["set", "night"]),
            ("scoreboard", vec!["players", "set"]),
            ("seed", vec![]),
            ("", vec![]),
        ] {
            assert!(!command_allowed_for_player(cmd, &args), "{cmd}");
        }
    }
}

#[cfg(test)]
mod connection_slot_tests {
    use super::*;
    #[test]
    fn panic_does_not_leak_connection_slot() {
        let count = AtomicUsize::new(1);
        let result = std::panic::catch_unwind(|| {
            let _slot = ConnectionSlot(&count);
            panic!("synthetic handler panic");
        });
        assert!(result.is_err());
        assert_eq!(count.load(Ordering::SeqCst), 0);
    }
}

#[cfg(test)]
mod handshake_security_tests {
    use super::*;
    #[test]
    fn valid_handshake_and_login_identity() {
        let mut h = Vec::new();
        write_varint(&mut h, 767);
        write_str(&mut h, "localhost");
        h.extend_from_slice(&25565u16.to_be_bytes());
        write_varint(&mut h, 2);
        assert_eq!(handshake_next_state(&h), Some(2));
        let mut login = Vec::new();
        write_str(&mut login, "Test_Player");
        login.extend_from_slice(&[7u8; 16]);
        assert_eq!(
            login_identity(&login),
            Some(("Test_Player".into(), [7; 16]))
        );
    }
    #[test]
    fn malformed_handshake_is_rejected_without_panicking() {
        let mut h = Vec::new();
        write_varint(&mut h, 767);
        write_varint(&mut h, i64::MAX);
        assert_eq!(handshake_next_state(&h), None);
        let mut truncated = Vec::new();
        write_varint(&mut truncated, 767);
        write_str(&mut truncated, "localhost");
        truncated.extend_from_slice(&25565u16.to_be_bytes());
        assert_eq!(handshake_next_state(&truncated), None);
        let mut bad_proto = Vec::new();
        write_varint(&mut bad_proto, 766);
        write_str(&mut bad_proto, "localhost");
        bad_proto.extend_from_slice(&25565u16.to_be_bytes());
        write_varint(&mut bad_proto, 2);
        assert_eq!(handshake_next_state(&bad_proto), None);
    }
    #[test]
    fn malformed_login_does_not_assume_zero_uuid() {
        let mut short = Vec::new();
        write_str(&mut short, "Alice");
        assert!(login_identity(&short).is_none());
        let mut long_name = Vec::new();
        write_str(&mut long_name, "APlayerWithAVeryLongUsername");
        long_name.extend_from_slice(&[1u8; 16]);
        assert!(login_identity(&long_name).is_none());
    }
}

#[cfg(test)]
mod resource_pack_url_tests {
    use super::resource_pack_url;
    #[test]
    fn loopback_only_by_default_and_explicit_external_url() {
        assert_eq!(
            resource_pack_url("127.0.0.1", None).as_deref(),
            Some("http://127.0.0.1:25598/pack.zip")
        );
        assert!(resource_pack_url("0.0.0.0", None).is_none());
        assert_eq!(
            resource_pack_url("0.0.0.0", Some("https://example.org/pack.zip")).as_deref(),
            Some("https://example.org/pack.zip")
        );
        assert!(resource_pack_url("0.0.0.0", Some("javascript:alert(1)")).is_none());
    }
}

#[cfg(test)]
mod save_integrity_tests {
    use super::*;
    #[test]
    fn wrapped_world_roundtrip_and_legacy_acceptance() {
        let legacy = vec![0u8, b'M', b'E', b'T', b'3', 0, 0, 0, 0, 0, 0, 0, 0, 0];
        assert_eq!(unwrap_world_payload(legacy.clone()), Ok(legacy.clone()));
        assert_eq!(
            unwrap_world_payload(wrap_world_payload(&legacy)),
            Ok(legacy)
        );
    }
    #[test]
    fn truncated_and_damaged_new_saves_are_rejected() {
        let original = wrap_world_payload(b"world-data");
        for n in 0..original.len() {
            let short = original[..n].to_vec();
            if n >= 3 {
                assert!(unwrap_world_payload(short).is_err(), "truncated to {n}");
            }
        }
        let mut corrupt = original;
        *corrupt.last_mut().unwrap() ^= 1;
        assert_eq!(unwrap_world_payload(corrupt), Err("save checksum mismatch"));
    }
}

#[cfg(test)]
mod save_backup_tests {
    use super::*;

    fn scratch(tag: &str) -> std::path::PathBuf {
        let dir = std::env::temp_dir().join(format!("spine-save-{tag}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    #[test]
    fn saves_keep_three_backup_generations_and_no_tmp_left() {
        let dir = scratch("gens");
        let world = dir.join("world.bin");
        // interval 0: every save rotates, so the generations are easy to read
        for n in 1..=5u8 {
            write_world_file(&world, &[n], Duration::ZERO).unwrap();
        }
        let read = |name: &str| std::fs::read(dir.join(name)).unwrap();
        assert_eq!(read("world.bin"), [5]);
        assert_eq!(read("world.bin.bak"), [4]);
        assert_eq!(read("world.bin.bak.1"), [3]);
        assert_eq!(read("world.bin.bak.2"), [2]);
        assert!(!dir.join("world.bin.bak.3").exists());
        assert!(!dir.join("world.bin.tmp").exists());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn older_generations_do_not_advance_within_the_interval() {
        let dir = scratch("interval");
        let world = dir.join("world.bin");
        for n in 1..=5u8 {
            write_world_file(&world, &[n], Duration::from_secs(3600)).unwrap();
        }
        let read = |name: &str| std::fs::read(dir.join(name)).unwrap();
        assert_eq!(read("world.bin"), [5]);
        assert_eq!(
            read("world.bin.bak"),
            [4],
            ".bak is always the previous save"
        );
        // bak.1 was created on the second save and is far younger than an hour
        assert_eq!(read("world.bin.bak.1"), [1]);
        assert!(!dir.join("world.bin.bak.2").exists());
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn a_failed_save_is_reported_with_its_path_and_keeps_the_old_world() {
        let dir = scratch("fail");
        let world = dir.join("world.bin");
        write_world_file(&world, b"good", Duration::ZERO).unwrap();
        // a directory squatting on the tmp path makes the tmp write fail
        std::fs::create_dir(dir.join("world.bin.tmp")).unwrap();
        let err = write_world_file(&world, b"new", Duration::ZERO).unwrap_err();
        assert!(err.contains("world.bin.tmp"), "{err}");
        assert_eq!(std::fs::read(&world).unwrap(), b"good");
        let _ = std::fs::remove_dir_all(&dir);
    }
}

#[cfg(test)]
mod skin_cache_tests {
    use super::*;

    fn skin(n: u8) -> Option<(String, String)> {
        Some((format!("v{n}"), format!("s{n}")))
    }

    #[test]
    fn the_cache_never_exceeds_its_cap_and_evicts_the_oldest() {
        let mut c = HashMap::new();
        let t0 = Instant::now();
        for i in 0..10u8 {
            skin_cache_put(
                &mut c,
                format!("n{i}"),
                skin(i),
                t0 + Duration::from_secs(i as u64),
                4,
            );
            assert!(c.len() <= 4);
        }
        assert!(skin_cache_get(&c, "n9", t0 + Duration::from_secs(9)).is_some());
        assert!(skin_cache_get(&c, "n0", t0 + Duration::from_secs(9)).is_none());
        // re-inserting an existing key at the cap does not evict anything
        let before = c.len();
        skin_cache_put(
            &mut c,
            "n9".into(),
            skin(99),
            t0 + Duration::from_secs(10),
            4,
        );
        assert_eq!(c.len(), before);
    }

    #[test]
    fn entries_expire_and_misses_expire_sooner_than_hits() {
        let mut c = HashMap::new();
        let t0 = Instant::now();
        skin_cache_put(&mut c, "hit".into(), skin(1), t0, 8);
        skin_cache_put(&mut c, "miss".into(), None, t0, 8);
        let soon = t0 + SKIN_TTL_MISS + Duration::from_secs(1);
        assert_eq!(skin_cache_get(&c, "miss", t0), Some(None));
        assert!(skin_cache_get(&c, "miss", soon).is_none());
        assert_eq!(skin_cache_get(&c, "hit", soon), Some(skin(1)));
        assert!(skin_cache_get(&c, "hit", t0 + SKIN_TTL_HIT + Duration::from_secs(1)).is_none());
        // expired entries are dropped before live ones when making room
        skin_cache_put(&mut c, "a".into(), skin(2), soon, 2);
        assert!(c.contains_key("hit") && c.contains_key("a") && !c.contains_key("miss"));
    }

    #[test]
    fn lookups_in_flight_are_bounded() {
        let mut held = Vec::new();
        while let Some(slot) = SkinLookupSlot::try_acquire() {
            held.push(slot);
            assert!(held.len() <= SKIN_LOOKUPS_MAX);
        }
        assert_eq!(held.len(), SKIN_LOOKUPS_MAX);
        drop(held);
        assert!(SkinLookupSlot::try_acquire().is_some());
    }
}
